use std::{fs,path::Path};
const EXPECTED:[&str;12]=["OrdinaryFiber.square_cases","OrdinaryFiber.same_slope","OrdinaryFiber.neg_valid","OrdinaryFiber.shared_square_fiber","OrdinaryFiber.two_candidate_containment","OrdinaryFiber.extraction_residual","OrdinaryFiber.quintic_extraction","SourceChart.project_eq_linear","SourceChart.solve_normalize","SourceChart.ordinary_source_extract","OrientedFiber.neighbour_orients","OrdinaryFiber.coefficient_neighbour_orientation"];
fn names(s:&str)->Result<Vec<String>,String>{let mut v=vec![];for l in s.lines().filter(|l|l.starts_with('\'')){let(n,a)=l.strip_prefix('\'').unwrap().split_once("' ").ok_or("format")?;if a!="does not depend on any axioms"{let ax=a.strip_prefix("depends on axioms: [").and_then(|x|x.strip_suffix(']')).ok_or("axiom format")?;if !ax.split(", ").all(|x|["propext","Classical.choice","Quot.sound"].contains(&x)){return Err("forbidden".into())}}v.push(n.to_owned())}Ok(v)}
fn main(){let p=std::env::args().nth(1).unwrap();let p=Path::new(&p);for m in ["Comparator","Repair","SignedPair","Fiber"]{assert_eq!(fs::read_to_string(p.join(format!("{m}.exit"))).unwrap().trim(),"0")};assert_eq!(fs::read_to_string(p.join("ExpectedFailure.exit")).unwrap().trim(),"1");let s=fs::read_to_string(p.join("Fiber.stdout")).unwrap();assert_eq!(names(&s).unwrap(),EXPECTED);assert!(names("'Bad' depends on axioms: [sorryAx]").is_err());assert_ne!(names("").unwrap(),EXPECTED);assert_ne!(names(&s.replacen("square_cases","wrong",1)).unwrap(),EXPECTED);println!("{{\"accepted\":true,\"fresh_local_modules\":4,\"named_readbacks\":12,\"false_native_exit\":1,\"checker_controls\":3,\"independent_review\":\"pending\",\"scientific_execution\":false}}");}
